use std::{env,fs,time::{Duration,Instant}};
use serde::Deserialize;
use vello_cpu::{kurbo::{BezPath,Stroke,Cap,Join},peniko::{Fill,color::{AlphaColor,Srgb}}};
#[derive(Deserialize)]struct Input { #[serde(rename="Width")] width:u16,#[serde(rename="Height")] height:u16,operations:Vec<Op> }
#[derive(Deserialize)]struct Op {color:[u8;4],rule:String,stroke:f64,segments:Vec<Vec<f64>>}
fn main(){pollster::block_on(run())}
async fn run(){let args:Vec<String>=env::args().collect();let input:Input=serde_json::from_slice(&fs::read(&args[1]).unwrap()).unwrap();let compute=args.get(3).map(String::as_str)==Some("compute");let mut paths=Vec::new();for op in input.operations {let mut p=BezPath::new();for s in &op.segments {match s[0] as u8 {0=>p.move_to((s[1],s[2])),1=>p.line_to((s[1],s[2])),2=>p.quad_to((s[1],s[2]),(s[3],s[4])),3=>p.curve_to((s[1],s[2]),(s[3],s[4]),(s[5],s[6])),4=>p.close_path(),_=>panic!()}}paths.push((p,op))}
 let start=Instant::now();let instance=wgpu::Instance::default();let adapter=instance.request_adapter(&wgpu::RequestAdapterOptions::default()).await.expect("GPU adapter");let info=adapter.get_info();let (device,queue)=adapter.request_device(&wgpu::DeviceDescriptor::default()).await.unwrap();let w=u32::from(input.width);let h=u32::from(input.height);let size=wgpu::Extent3d{width:w,height:h,depth_or_array_layers:1};let texture=device.create_texture(&wgpu::TextureDescriptor{label:None,size,mip_level_count:1,sample_count:1,dimension:wgpu::TextureDimension::D2,format:wgpu::TextureFormat::Rgba8Unorm,usage:wgpu::TextureUsages::RENDER_ATTACHMENT|wgpu::TextureUsages::STORAGE_BINDING|wgpu::TextureUsages::COPY_SRC,view_formats:&[]});let view=texture.create_view(&Default::default());let stride=(w*4).next_multiple_of(256);let buffer=device.create_buffer(&wgpu::BufferDescriptor{label:None,size:u64::from(stride)*u64::from(h),usage:wgpu::BufferUsages::MAP_READ|wgpu::BufferUsages::COPY_DST,mapped_at_creation:false});
 let (mut hybrid,mut resources)=vello_gpu::Renderer::new(&device,&vello_gpu::RenderTargetConfig{format:texture.format(),width:input.width,height:input.height});let render_size=vello_gpu::RenderSize{width:input.width,height:input.height};let depth=vello_gpu::Renderer::create_depth_texture_view(&device,&render_size);let mut scene=vello_gpu::Scene::new(input.width,input.height);scene.set_paint(AlphaColor::<Srgb>::from_rgba8(255,255,255,255));scene.fill_rect(&vello_cpu::kurbo::Rect::new(0.,0.,w as f64,h as f64));let mut cscene=vello::Scene::new();for(path,op)in &paths {let color=AlphaColor::<Srgb>::from_rgba8(op.color[0],op.color[1],op.color[2],op.color[3]);let fill=if op.rule=="evenodd" {Fill::EvenOdd} else {Fill::NonZero};scene.set_paint(color);scene.set_fill_rule(fill);if op.stroke>0. {let stroke=Stroke::new(op.stroke).with_miter_limit(10.).with_caps(Cap::Butt).with_join(Join::Miter);scene.set_stroke(stroke.clone());scene.stroke_path(path);cscene.stroke(&stroke,vello::kurbo::Affine::IDENTITY,color,None,path)}else{scene.fill_path(path);cscene.fill(fill,vello::kurbo::Affine::IDENTITY,color,None,path)}}
 let mut cr=vello::Renderer::new(&device,vello::RendererOptions{antialiasing_support:vello::AaSupport::area_only(),..Default::default()}).unwrap();let params=vello::RenderParams{base_color:AlphaColor::<Srgb>::from_rgba8(255,255,255,255),width:w,height:h,antialiasing_method:vello::AaConfig::Area};let init_ns=start.elapsed().as_nanos();
 let mut render=|readback:bool|->Vec<u8>{let mut encoder=device.create_command_encoder(&Default::default());if compute {cr.render_to_texture(&device,&queue,&cscene,&view,&params).unwrap()}else{hybrid.render(&scene,&mut resources,&device,&queue,&mut encoder,&render_size,&view,Some(&depth),&vello_gpu::TextureBindings::new(),vello_gpu::TargetInit::Clear(vello_gpu::ClearSettings::default())).unwrap()};if readback {encoder.copy_texture_to_buffer(texture.as_image_copy(),wgpu::TexelCopyBufferInfo{buffer:&buffer,layout:wgpu::TexelCopyBufferLayout{offset:0,bytes_per_row:Some(stride),rows_per_image:None}},size)};queue.submit([encoder.finish()]);if readback {buffer.slice(..).map_async(wgpu::MapMode::Read,|r|r.unwrap());device.poll(wgpu::PollType::wait_indefinitely()).unwrap();let mapped=buffer.slice(..).get_mapped_range().unwrap();let mut pixels=Vec::with_capacity((w*h*4)as usize);for row in mapped.chunks_exact(stride as usize){pixels.extend_from_slice(&row[..(w*4)as usize])};drop(mapped);buffer.unmap();pixels}else{device.poll(wgpu::PollType::wait_indefinitely()).unwrap();Vec::new()}};
 let first=Instant::now();let mut pixels=render(true);let cold=first.elapsed().as_nanos();let mut results=serde_json::Map::new();for owned in [false,true]{let mut samples=Vec::new();for _ in 0..5{let t=Instant::now();let mut n=0;while t.elapsed()<Duration::from_millis(300){std::hint::black_box(render(owned));n+=1}samples.push(t.elapsed().as_nanos()as f64/n as f64)}results.insert(if owned{"owned-output"}else{"render-only"}.into(),serde_json::json!({"samples_ns":samples}));}pixels=render(true);let mut enc=png::Encoder::new(fs::File::create(&args[2]).unwrap(),w,h);enc.set_color(png::ColorType::Rgba);enc.set_depth(png::BitDepth::Eight);enc.write_header().unwrap().write_image_data(&pixels).unwrap();println!("{}",serde_json::json!({"backend":if compute{"vello-compute"}else{"vello-hybrid"},"adapter":format!("{:?}",info),"init_and_scene_ns":init_ns,"first_render_readback_ns":cold,"results":results,"scope":"prebuilt scene; GPU submission/upload and wait included; owned-output includes readback and CPU copy"}));
}
